    /// English / Arabic strings. L.T("key", args) returns the text in the current language.
    public static class L
    {
        public static string T(string key, params object[] args)
        {
            string[] v;
            string s = S.TryGetValue(key, out v) ? (Theme.RTL ? v[1] : v[0]) : key;
            if (args != null && args.Length > 0) try { s = string.Format(s, args); } catch { }
            return s;
        }

        public static bool Has(string key) { return S.ContainsKey(key); }
        /// Every text, for the self-test.
        public static IEnumerable<KeyValuePair<string, string[]>> All { get { return S; } }

        /// The text in both languages (for searching in either one).
        public static string Both(string key)
        {
            string[] v;
            return key != null && S.TryGetValue(key, out v) ? v[0] + " " + v[1] : "";
        }

