            { "ao_bg", new[] { "Background remover (AI)", "مزيل الخلفية (ذكاء اصطناعي)" } },
            { "ao_upscale", new[] { "Photo upscaler (Real-ESRGAN)", "مكبّر الصور (Real-ESRGAN)" } },
