            { "ao_node", new[] { "Node.js", "Node.js" } },
            { "wn_ps170_t", new[] { "A new photo studio", "استوديو صور جديد" } },
            { "wn_ps170_d", new[] { "Opening a photo starts editing it, in layers: text, photos, painting and adjustments (Levels, Curves, Hue) you can show, hide, lock, group and reorder. Selections with Select subject, full history, and projects that keep every layer.", "فتح أي صورة يبدأ تعديلها في طبقات: نصوص وصور ورسم وتعديلات (المستويات والمنحنيات ودرجة اللون) يمكنك إظهارها وإخفاؤها وقفلها وتجميعها وترتيبها. تحديد مع تحديد العنصر، وسجل كامل، ومشاريع تحتفظ بكل الطبقات." } },
            { "wn_remove170_t", new[] { "Remove object", "إزالة عنصر" } },
            { "wn_remove170_d", new[] { "Paint over a person, a sign or a stain (J) and it's filled from the photo around it — right on your PC, nothing is uploaded. Export shows the file size as you pick the format and quality.", "ارسم فوق شخص أو لافتة أو بقعة (J) فيُملأ من الصورة المحيطة — على جهازك مباشرة دون رفع أي شيء. ويُظهر التصدير حجم الملف وأنت تختار الصيغة والجودة." } },
            { "wn_vs170_t", new[] { "A new video studio", "استوديو فيديو جديد" } },
            { "wn_vs170_d", new[] { "A timeline with tracks for the video, overlays, texts, music and captions. Split (S), trim, move between tracks, a transition for each cut, speed from 0.1× to 10×, shapes for Reels and YouTube with a blurred fill.", "مخطط زمني بمسارات للفيديو والصور الفوقية والنصوص والموسيقى والتعليقات. التقسيم (S) والقص والنقل بين المسارات، وانتقال لكل قطع، وسرعة من ‎0.1×‎ إلى ‎10×‎، وأشكال لريلز ويوتيوب بخلفية ضبابية." } },
            { "wn_keys170_t", new[] { "Keyframes and animations", "الإطارات المفتاحية والحركة" } },
            { "wn_keys170_d", new[] { "Make overlays and texts move, grow, turn and fade with keyframes (◆), and give them in and out animations: fade, slide, pop or typing. Detach a video's sound, take out background noise, and fade or duck the music.", "حرّك الصور الفوقية والنصوص وكبّرها ودوّرها وأخفها تدريجيًا بالإطارات المفتاحية (◆)، وأضف لها حركة ظهور واختفاء: تلاشٍ أو انزلاق أو قفزة أو كتابة. افصل صوت الفيديو، وأزل الضجيج، واخفض الموسيقى تدريجيًا." } },
            { "wn_caps170_t", new[] { "Captions with style", "تعليقات بأنماط مختلفة" } },
            { "wn_caps170_d", new[] { "Auto captions (on your PC) land on their own track, with styles like word highlight and bold pop; fix any word in a list. Export picks the size, smoothness and quality, with the file size shown.", "تُوضع التعليقات التلقائية (على جهازك) على مسار خاص بأنماط مثل إبراز الكلمة والعريض البارز، وتصحيح أي كلمة من قائمة. ويختار التصدير الحجم والسلاسة والجودة مع إظهار حجم الملف." } },
            { "wn_fixes170_t", new[] { "Smaller fixes", "إصلاحات أصغر" } },
            { "dl_klipy_blocked", new[] { "KLIPY only opens its GIF pages for a person in a web browser, so this link can't be read here. Open the GIF in your browser, right-click it, choose \"Copy image address\" and paste that link instead.", "لا يفتح KLIPY صفحات صوره المتحركة إلا لشخص يستخدم متصفح الويب، لذلك لا يمكن قراءة هذا الرابط هنا. افتح الصورة في متصفحك، وانقر عليها بزر الماوس الأيمن، واختر «نسخ عنوان الصورة»، ثم الصق ذلك الرابط بدلًا منه." } },
            { "wn_fixes170_d", new[] { "Watch folders put the original in the Recycle Bin once it's converted. Dragging a folder onto the Donut Wheel offers Convert, Compress, Rename and Duplicates. Duplicates shows the full folder names, and Fadi Tools never opens Edge for a GIF any more.", "تنقل المجلدات المراقَبة الملف الأصلي إلى سلة المحذوفات بعد تحويله. وسحب مجلد إلى عجلة الدونات يعرض التحويل والضغط وإعادة التسمية والمكررات. وتُظهر المكررات أسماء المجلدات كاملة، ولم يعد Fadi Tools يفتح Edge لتنزيل صورة GIF." } },
            // 1.6.4
            { "wn_look164_t", new[] { "A clearer look", "مظهر أوضح" } },
            { "wn_look164_d", new[] { "Words on orange buttons and small grey hints are easier to read, the light look is a calmer grey, titles use Windows 11's own type, and a small orange ring marks the page you're on.", "صارت الكلمات على الأزرار البرتقالية والتلميحات الرمادية الصغيرة أسهل قراءة، والمظهر الفاتح رمادي أهدأ، والعناوين بخط Windows 11 نفسه، وحلقة برتقالية صغيرة تدل على الصفحة التي أنت فيها." } },
            { "wn_empty164_t", new[] { "Pages that show what they do", "صفحات تُريك ما تفعله" } },
            { "wn_empty164_d", new[] { "Rename shows an example, Duplicates looks in Downloads, Pictures or the Desktop in one click, and the File inspector and Studio list your recent files.", "تعرض إعادة التسمية مثالاً، ويبحث فاحص المكررات في التنزيلات أو الصور أو سطح المكتب بنقرة، ويعرض فاحص الملفات والاستوديو ملفاتك الأخيرة." } },
            { "wn_studio164_t", new[] { "Photos, PDF and Videos in the Studio", "الصور وPDF والفيديو في الاستوديو" } },
            { "wn_studio164_d", new[] { "The Studio has three tabs. Compress has its button at the bottom, like Convert, and Windows integration in Settings is in three groups.", "للاستوديو ثلاث علامات تبويب. وزر الضغط صار في الأسفل مثل التحويل، وتكامل Windows في الإعدادات صار في ثلاث مجموعات." } },
            // 1.6.3
            { "wn_pdfedit_t", new[] { "Edit the text in PDFs", "تعديل النص في ملفات PDF" } },
            { "wn_pdfedit_d", new[] { "Studio → PDF → Edit text: click any line and type over it, add new text, or erase something. Everything else in the PDF stays exactly as it was.", "الاستوديو ← PDF ← تعديل النص: انقر على أي سطر واكتب فوقه، أو أضف نصًا جديدًا، أو امسح شيئًا. يبقى كل ما عدا ذلك في الملف كما هو تمامًا." } },
            { "wn_wheeltools_t", new[] { "AI Scale, Resize, Rotate and Trim on the wheel", "التكبير بالذكاء الاصطناعي وتغيير الحجم والتدوير والقص في العجلة" } },
            { "wn_wheeltools_d", new[] { "New Donut Wheel slices open small windows of their own. Drag several pictures to combine them into one PDF, or several PDFs to merge them.", "أقسام جديدة في عجلة الدونات تفتح نوافذ صغيرة خاصة بها. اسحب عدة صور لدمجها في PDF واحد، أو عدة ملفات PDF لدمجها." } },
            { "wn_cmpslider_t", new[] { "Compress to the size you want", "اضغط إلى الحجم الذي تريده" } },
            { "wn_cmpslider_d", new[] { "Compress (on the wheel and on the Compress page) has a slider: 50% makes the file half its size, 200% twice; the new size shows as you move it.", "للضغط (في العجلة وفي صفحة الضغط) شريط تمرير: 50% يجعل الملف بنصف حجمه و200% بضعفه، ويظهر الحجم الجديد أثناء التحريك." } },
            { "wn_recipes_t", new[] { "Recipes and watch folders", "الوصفات والمجلدات المراقَبة" } },
            { "wn_recipes_d", new[] { "Save several steps as one wheel slice (like crop → resize → JPG), and have files that land in a folder converted for you.", "احفظ عدة خطوات كقسم واحد في العجلة (مثل القص ← تغيير الحجم ← JPG)، واجعل الملفات التي تصل إلى مجلد تُحوَّل تلقائيًا." } },
            { "wn_startup_t", new[] { "Start with Windows", "التشغيل مع Windows" } },
            { "wn_startup_d", new[] { "A new setting starts Fadi Tools by the clock when you sign in (off unless you turn it on). Notifications now come only for long tasks or failures, quietly, unless you choose otherwise in Settings.", "إعداد جديد يشغّل أدوات فادي بجانب الساعة عند تسجيل الدخول (متوقف ما لم تفعّله). وتصل الإشعارات الآن للمهام الطويلة أو الفاشلة فقط، وبلا صوت، ما لم تختر غير ذلك في الإعدادات." } },
            { "pe_tool", new[] { "Edit text", "تعديل النص" } },
            { "pe_tool_tip", new[] { "Change the words on the pages: click a line and type, add new text, or erase something", "غيّر الكلمات في الصفحات: انقر على سطر واكتب، أو أضف نصًا جديدًا، أو امسح شيئًا" } },
