            { "pe_no_text", new[] { "No text found on this page. Use Add text to write on it.", "لم يُعثر على نص في هذه الصفحة. استخدم «إضافة نص» للكتابة عليها." } },
            { "pe_hint_edit", new[] { "Point at a line of text and click it to change what it says. Press Enter when done; Esc puts it back. Pick a change again to adjust its size, letters or colour.", "أشر إلى سطر نص وانقر عليه لتغيير ما فيه. اضغط Enter عند الانتهاء؛ وEsc يعيده كما كان. اختر التغيير مرة أخرى لضبط حجمه أو خطه أو لونه." } },
            { "pe_hint_add", new[] { "Click anywhere on the page and type to add new text there.", "انقر في أي مكان من الصفحة واكتب لإضافة نص جديد هناك." } },
            { "pe_hint_erase", new[] { "Drag over anything on the page to wipe it clean (it's covered with the page's own colour).", "اسحب فوق أي شيء في الصفحة لمسحه (يُغطّى بلون الصفحة نفسه)." } },
            { "pe_hint_area", new[] { "An erased area. Press Delete to bring back what was there.", "منطقة ممسوحة. اضغط Delete لإعادة ما كان فيها." } },
