            { "up_dl_bad", new[] { "The AI engine download didn't have what was expected. Try again later.", "لم يحتوِ تنزيل محرك الذكاء الاصطناعي على المتوقع. حاول لاحقًا." } },
            { "up_no_gpu", new[] { "AI Scale needs a graphics card that supports Vulkan, and none was found. Updating the graphics driver often fixes this.", "يحتاج التكبير بالذكاء الاصطناعي إلى بطاقة رسومات تدعم Vulkan ولم يُعثر على واحدة. غالبًا يحل تحديث تعريف بطاقة الرسومات ذلك." } },
